-- Room catalog imported from mfu_rooms.csv
-- Keeps every source row, including repeated room_id values.
CREATE TABLE IF NOT EXISTS room_catalog (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    room_id TEXT NOT NULL,
    building_name TEXT NOT NULL,
    building_code TEXT NOT NULL,
    zone TEXT,
    floor TEXT NOT NULL,
    capacity INTEGER NOT NULL CHECK(capacity > 0),
    capacity_source TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_room_catalog_building_floor ON room_catalog(building_code, floor);
CREATE INDEX IF NOT EXISTS idx_room_catalog_room_id ON room_catalog(room_id);

